export function loadUiLanguage(): UiLanguage {
  try {
    return window.localStorage.getItem(languageStorageKey) === "en" ? "en" : "zh-CN";
  } catch {
    return "zh-CN";
  }
}

export function saveUiLanguage(language: UiLanguage): void {
  try { window.localStorage.setItem(languageStorageKey, language); } catch { /* Presentation preference is optional. */ }
}

export function translate(language: UiLanguage, key: string, values: Record<string, string | number> = {}): string {
  const template = independentResourceHelp[key]?.[language] ?? messages[language][key] ?? messages.en[key] ?? key;
  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? `{${name}}`));
}

export function moduleLabel(language: UiLanguage, moduleId: string): string {
  return translate(language, { caption: "moduleCaption", classify: "moduleClassify", replace: "moduleReplace", ocr: "moduleOcr", nl: "moduleNl", count_review: "moduleCountReview", dropout: "modulePolicy", token_budget: "moduleTokenBudget", export: "moduleExport" }[moduleId] ?? moduleId);
}

export function statusLabel(language: UiLanguage, status: string): string {
  return translate(language, `status_${status}`);
}

export function formatLabel(language: UiLanguage, format: string): string {
  return translate(language, { both: "both", json: "jsonOnly", flat_txt: "flatTxtOnly" }[format] ?? format);
}
